// ============================================================
// SAVE DASHBOARD SNAPSHOT
// ============================================================

msg.dashboard_data = dashboardPayload;

msg.payload = dashboardPayload;

msg.sample_id =
    dashboardPayload.sample_id;

flow.set(
    "last_pyrowatch_payload",
    dashboardPayload
);


// ============================================================
// NODE STATUS
// ============================================================

node.status({

    fill: "green",

    shape: "dot",

    text:
        `Snapshot ${dashboardPayload.sample_id || dashboardPayload.node_id}`

});

return msg;

const data = flow.get("last_pyrowatch_payload");

if (!data) {
    msg.statusCode = 404;
    msg.payload = {
        success: false,
        message: "Belum ada data sensor"
    };
    return msg;
}

msg.statusCode = 200;
msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    success: true,
    data: data
};

return msg;

const sample =
    msg.analytics_data ||
    msg.sensor_data ||
    {};


// ============================================================
// FALLBACK ML RESULT
// ============================================================

msg.ml_result = {

    forecast_status:
        "ML_REQUEST_FAILED",

    forecast_horizon_minutes:
        15,

    insight_text:
        "Prediksi tidak tersedia karena API ML gagal diakses.",

    risk_level:
        sample.fri_level || "UNKNOWN",

    trend:
        "UNKNOWN",

    highlights: [],

    recommendations: {

        // ----------------------------------------------------
        // 1. DETEKSI DAN PEMANTAUAN DINI
        // ----------------------------------------------------

        monitoring:
            "Periksa koneksi sensor dan kelengkapan data yang diterima Node-RED.",


        // ----------------------------------------------------
        // 2. PENCEGAHAN DAN PENANGANAN AWAL
        // ----------------------------------------------------

        early_response:
            "Jangan gunakan prediksi yang gagal diproses sebagai dasar tunggal tindakan darurat. Ikuti SOP dan verifikasi lapangan.",


        // ----------------------------------------------------
        // 3. PERLINDUNGAN AREA DAN KESELAMATAN
        // ----------------------------------------------------

        area_protection:
            "Pertahankan prosedur keselamatan dan gunakan informasi lapangan untuk menentukan area rentan.",


        // ----------------------------------------------------
        // 4. KOORDINASI DAN KESIAPSIAGAAN
        // ----------------------------------------------------

        coordination:
            "Periksa status layanan ML, koneksi jaringan, dan log API sebelum mengaktifkan kembali prediksi."

    },

    forecast_model_version:
        null,

    input_status:
        "ML_API_UNAVAILABLE"

};


// ============================================================
// RESTORE ORIGINAL SENSOR DATA
// ============================================================

msg.payload = {
    ...sample
};

delete msg.error;


// ============================================================
// NODE STATUS
// ============================================================

node.status({

    fill: "red",

    shape: "ring",

    text: "ML API gagal"

});

return msg;

const f = msg.ml_forecast || {};
const sample = msg.payload || {};

if (!f.node_id || !f.sample_timestamp) {
    node.warn("Forecast tidak disimpan: node_id atau sample_timestamp tidak tersedia.");
    return null;
}

const forecastTimestamp =
    f.forecast_timestamp ||
    new Date(
        new Date(f.sample_timestamp).getTime() + 15 * 60 * 1000
    ).toISOString();

msg.params = [
    f.node_id,
    f.sample_timestamp,
    forecastTimestamp,
    Number(f.forecast_horizon_minutes ?? 15),

    Number.isFinite(Number(f.current_fri))
        ? Number(f.current_fri)
        : null,

    Number.isFinite(Number(f.future_fri))
        ? Number(f.future_fri)
        : null,

    f.future_fri_level ?? null,
    f.future_fri_range ?? null,

    Number.isFinite(Number(f.future_wind_speed))
        ? Number(f.future_wind_speed)
        : null,

    f.future_wind_speed_range ?? null,
    f.future_wind_direction ?? null,

    f.future_spread_rate_range ?? null,
    f.future_spread_direction ?? null,

    Number.isFinite(Number(f.spread_direction_probability))
        ? Number(f.spread_direction_probability)
        : null,

    Number.isFinite(Number(f.forecast_confidence))
        ? Number(f.forecast_confidence)
        : null,

    f.forecast_status ?? "UNKNOWN",
    f.forecast_interpretation ?? null,
    f.forecast_model_version ?? null
];

node.warn({
    message: "SQLite ML parameters prepared",
    parameterCount: msg.params.length,
    node_id: f.node_id
});

return msg;
